  ops[40] = function() if fz then local e = rd(pc) pc = pc + 1 if e > 127 then e = e - 256 end pc = (pc + e) % 65536 return 12 end pc = pc + 1 return 8 end
  ops[41] = function() local hl = h * 256 + l local v = h * 256 + l local r = hl + v fn = false fh = (hl % 4096 + v % 4096 > 4095) if r > 65535 then r = r - 65536 fc = 1 else fc = 0 end l = r % 256 h = (r - l) / 256 return 8 end
  ops[42] = function() a = rd(h * 256 + l) l = l + 1 if l > 255 then l = 0 h = h + 1 if h > 255 then h = 0 end end return 8 end
