  -- Runs the machine until the next vertical blank (one video frame).
  -- render = false skips drawing (the game still advances): use it for
  -- frames that will not be shown.
  function m.runFrame(render)
    doRender = (render ~= false)
    frameDone = false
    repeat
      while clk < evt do
        if irqPending then
          halted = false
          if ime then
            local p = AND8[ie * 256 + ifl] % 32
            local bitv, vec
            if p % 2 == 1 then bitv, vec = 1, 0x40
            elseif p % 4 >= 2 then bitv, vec = 2, 0x48
            elseif p % 8 >= 4 then bitv, vec = 4, 0x50
            elseif p % 16 >= 8 then bitv, vec = 8, 0x58
            else bitv, vec = 16, 0x60 end
            ifl = ifl - bitv
            irqPending = (p ~= bitv)
            ime = false
            sp = (sp - 2) % 65536
            wr(sp + 1, floor(pc / 256))
            wr(sp, pc % 256)
            pc = vec
            clk = clk + 20
          end
        end
        if halted then
          clk = evt
          break
        end
        if eiDelay then ime, eiDelay = true, false end
        local op = rd(pc)
        pc = pc + 1
        clk = clk + ops[op]()
      end
      if clk >= link.at then linkEvent() end
      if clk >= timNext then timSync() end
      while clk >= ppuNext do ppuEvent() end
      resched()
    until frameDone
  end

  -- name: "right" "left" "up" "down" "a" "b" "select" "start"
  local KEYS = { right = { 0, 1 }, left = { 0, 2 }, up = { 0, 4 }, down = { 0, 8 },
                 a = { 1, 1 }, b = { 1, 2 }, select = { 1, 4 }, start = { 1, 8 } }
  function m.setKey(name, down)
    local k = KEYS[name]
    if not k then return end
    local cur = (k[1] == 0) and dpad or btn
    local isUp = (cur % (k[2] * 2) >= k[2])
    if down and isUp then
      cur = cur - k[2]
      reqInt(16)
    elseif not down and not isUp then
      cur = cur + k[2]
    end
    if k[1] == 0 then dpad = cur else btn = cur end
  end

  function m.releaseAllKeys() dpad, btn = 15, 15 end

  -- Battery-backed save RAM and clock, in a form SavedVariables can hold.
  function m.getSave()
    local out = { ram = {}, rtcBase = rtcBase, rtcHaltAt = rtcHaltAt, title = m.title }
    for i = 0, ramBanks - 1 do out.ram[i + 1] = ramToHex(ext[i]) end
    saveDirty = false
    return out
  end

  function m.saveDirty() return saveDirty end

  -- ------------------------------------------------------ save states ---
  -- Everything needed to continue from this exact instant. Strings are raw
  -- bytes (see GB.encodeState for a SavedVariables-safe form). prev = the
  -- previous state taken from this machine, if any: unchanged save RAM is
  -- shared with it instead of copied (rewind takes many states a minute).
  -- (Split into small functions: Lua allows 60 captured variables each.)
  local function getCpu() return a, b, c, d, e, h, l, sp, pc, fz, fn, fh, fc, ime, eiDelay, halted, ie, ifl end
  local function setCpu(r)
    a, b, c, d, e, h, l, sp, pc, fz, fn, fh, fc, ime, eiDelay, halted, ie, ifl =
      r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9], r[10], r[11], r[12], r[13], r[14], r[15], r[16], r[17], r[18]
    irqPending = (AND8[ie * 256 + ifl] % 32 ~= 0)
  end
  local function getClk() return clk, ds, key1prep, divBase, tima, tma, tac, timLast end
  local function setClk(r)
    clk, ds, key1prep, divBase, tima, tma, tac, timLast = r[19], r[20], r[21], r[22], r[23], r[24], r[25], r[26]
    mul = ds and 2 or 1
    timOn = (tac >= 4)
    local sel2 = tac % 4
    timPeriod = (sel2 == 0 and 1024) or (sel2 == 1 and 16) or (sel2 == 2 and 64) or 256
  end
  local function getPpu()
    return lcdc, stat, scy, scx, ly, lyc, wy, wx, bgp, obp0, obp1, mode, ppuNext, winLine,
      bcps, ocps, vbk, svbk, hdmaActive, hdmaRem, hdmaSrc, hdmaDst
  end
  local function setPpu(r)
    lcdc, stat, scy, scx, ly, lyc, wy, wx, bgp, obp0, obp1, mode, ppuNext, winLine =
      r[27], r[28], r[29], r[30], r[31], r[32], r[33], r[34], r[35], r[36], r[37], r[38], r[39], r[40]
    bcps, ocps, vbk, svbk, hdmaActive, hdmaRem, hdmaSrc, hdmaDst = r[41], r[42], r[43], r[44], r[45], r[46], r[47], r[48]
    bgOn, objOn, objTall = (lcdc % 2 == 1), (lcdc % 4 >= 2), (lcdc % 8 >= 4)
    bgMapHi, tileLo, winOn = (lcdc % 16 >= 8), (lcdc % 32 >= 16), (lcdc % 64 >= 32)
    winMapHi, lcdOn = (lcdc % 128 >= 64), (lcdc >= 128)
  end
  local function getMbc()
    return ramEnable, ramSel, romBank, romHi, mbcMode, latchPrev,
      rtcLatch[8], rtcLatch[9], rtcLatch[10], rtcLatch[11], rtcLatch[12], rtcBase, rtcHaltAt or false, joySel
  end
  local function setMbc(r)
    ramEnable, ramSel, romBank, romHi, mbcMode, latchPrev = r[49], r[50], r[51], r[52], r[53], r[54]
    rtcLatch[8], rtcLatch[9], rtcLatch[10], rtcLatch[11], rtcLatch[12] = r[55], r[56], r[57], r[58], r[59]
    rtcBase, rtcHaltAt, joySel = r[60], r[61] or nil, r[62]
    if mbc == 1 then
      romb = bank((mbcMode == 1) and romBank or (romHi * 32 + romBank))
      extb = ext[(mbcMode == 1 and ramBanks > 0) and (romHi % ramBanks) or 0]
    else
      romb = bank(romBank)
      if ramBanks > 0 then
        if mbc == 3 then
          if ramSel < 8 then extb = ext[ramSel % ramBanks] end
        else
          extb = ext[ramSel % ramBanks]
        end
      end
    end
  end
  local function add(r, ...)
    for i = 1, select("#", ...) do r[#r + 1] = (select(i, ...)) end
  end

  function m.saveState(prev)
    local r = {}
    add(r, getCpu())
    add(r, getClk())
    add(r, getPpu())
    add(r, getMbc())
    local mm = {
      vram0 = pack(vram0, 0x2000), vram1 = pack(vram1, 0x2000),
      oam = pack(oam, 0xA0), hram = pack(hram, 0x80), io = pack(io, 0x80),
      bgpd = pack(bgpd, 64), obpd = pack(obpd, 64),
    }
    for i = 0, 7 do mm["w" .. i] = pack(wram[i], 0x1000) end
    local shareExt = prev and prev.extGen == extGen
    for i = 0, ramBanks - 1 do
      mm["x" .. i] = shareExt and prev.m["x" .. i] or pack(ext[i], 0x2000)
    end
    return { v = 1, r = r, m = mm, extGen = extGen }
  end

  local function setMemory(mm)
    unpackInto(vram0, mm.vram0, 0x2000)
    unpackInto(vram1, mm.vram1, 0x2000)
    unpackInto(oam, mm.oam, 0xA0)
    unpackInto(hram, mm.hram, 0x80)
    unpackInto(io, mm.io, 0x80)
    unpackInto(bgpd, mm.bgpd, 64)
    unpackInto(obpd, mm.obpd, 64)
    for i = 0, 7 do unpackInto(wram[i], mm["w" .. i], 0x1000) end
    for i = 0, ramBanks - 1 do unpackInto(ext[i], mm["x" .. i], 0x2000) end
    extGen = extGen + 1
    saveDirty = true
    for k = 0, 31 do
      bgcol[k] = (bgpd[k * 2] + bgpd[k * 2 + 1] * 256) % 32768
      objcol[k] = (obpd[k * 2] + obpd[k * 2 + 1] * 256) % 32768
    end
    dmgPal()
    allStale()
    if vbk == 1 then vram, tc = vram1, tc1 else vram, tc = vram0, tc0 end
    wramb = wram[svbk == 0 and 1 or svbk]
    -- the per-pixel tile cache is derived from VRAM
    for _, pair in ipairs({ { vram0, tc0 }, { vram1, tc1 } }) do
      local vr, t = pair[1], pair[2]
      for i = 0, 0x17FE, 2 do
        local bl, bh = BITS[vr[i]], BITS[vr[i + 1]]
        local base = i * 4
        t[base], t[base + 1], t[base + 2], t[base + 3] = bl[1] + bh[1] * 2, bl[2] + bh[2] * 2, bl[3] + bh[3] * 2, bl[4] + bh[4] * 2
        t[base + 4], t[base + 5], t[base + 6], t[base + 7] = bl[5] + bh[5] * 2, bl[6] + bh[6] * 2, bl[7] + bh[7] * 2, bl[8] + bh[8] * 2
      end
    end
  end

  function m.loadState(st)
    if type(st) ~= "table" or st.v ~= 1 or type(st.r) ~= "table" or type(st.m) ~= "table" then
      return false, "not a save state"
    end
    local mm, r = st.m, st.r
    for _, key in ipairs({ "vram0", "vram1", "oam", "hram", "io", "bgpd", "obpd", "w0", "w7" }) do
      if type(mm[key]) ~= "string" then return false, "save state is incomplete" end
    end
    if #mm.vram0 ~= 0x2000 or #mm.w0 ~= 0x1000 or #r < 62 then return false, "save state is damaged" end
    for i = 0, ramBanks - 1 do
      if type(mm["x" .. i]) ~= "string" or #mm["x" .. i] ~= 0x2000 then
        return false, "save state is from a different game"
      end
    end
    setCpu(r)
    setClk(r)
    setPpu(r)
    setMemory(mm)
    setMbc(r)
    timSync()
    dpad, btn = 15, 15
    -- a byte that was on its way out when the state was taken starts again
    link.at = HUGE
    if io[2] >= 128 and (io[2] % 2 == 1 or link.clock) then link.at = clk + 4096 end
    resched()
    return true
  end

  -- ------------------------------------------------------ tools' hooks ---
  -- Run the CPU until it reaches pcStop (or maxCycles pass). Slower than
  -- runFrame; for tools that call a game's own routines directly.
  local function events()
    if clk >= link.at then linkEvent() end
    if clk >= timNext then timSync() end
    while clk >= ppuNext do ppuEvent() end
    resched()
  end
  function m.runUntil(pcStop, maxCycles)
    local limit = clk + maxCycles
    while pc ~= pcStop and clk < limit do
      if clk >= evt then events() end
      if halted then
        if irqPending then halted = false else clk = evt end
      else
        if irqPending and ime then
          local p = AND8[ie * 256 + ifl] % 32
          local bitv, vec
          if p % 2 == 1 then bitv, vec = 1, 0x40
          elseif p % 4 >= 2 then bitv, vec = 2, 0x48
          elseif p % 8 >= 4 then bitv, vec = 4, 0x50
          elseif p % 16 >= 8 then bitv, vec = 8, 0x58
          else bitv, vec = 16, 0x60 end
          ifl = ifl - bitv
          irqPending = (p ~= bitv)
          ime = false
          sp = (sp - 2) % 65536
          wr(sp + 1, floor(pc / 256))
          wr(sp, pc % 256)
          pc = vec
          clk = clk + 20
        end
        if eiDelay then ime, eiDelay = true, false end
        local op = rd(pc)
        pc = pc + 1
        clk = clk + ops[op]()
      end
    end
    return pc == pcStop
  end
  -- let time pass without running the CPU
  function m.idle(cycles)
    local target = clk + cycles
    while clk < target do
      clk = (evt < target) and evt or target
      if clk >= evt then events() end
    end
  end
  function m.clock() return clk end
  -- set CPU registers: { pc =, sp =, a =, b =, c =, d =, e =, h =, l =, ime = }
  function m.setCPU(t)
    if t.pc then pc = t.pc end
    if t.sp then sp = t.sp end
    if t.a then a = t.a end
    if t.b then b = t.b end
    if t.c then c = t.c end
    if t.d then d = t.d end
    if t.e then e = t.e end
    if t.h then h = t.h end
    if t.l then l = t.l end
    if t.ime ~= nil then ime, eiDelay = t.ime, false end
    if t.halted ~= nil then halted = t.halted end
  end
  function m.getCPU()
    return { pc = pc, sp = sp, a = a, b = b, c = c, d = d, e = e, h = h, l = l, ime = ime, romBank = romBank }
  end

  -- Breakpoints: call fn(regs) whenever the CPU is about to execute the
  -- instruction at one of these ROM addresses, then carry on as normal.
  -- list = { { bank =, addr =, fn = }, ... }. They cost nothing elsewhere:
  -- the byte at each address is swapped for an opcode the Game Boy never
  -- uses (0xD3), whose handler runs fn and then the real instruction.
  -- owner (any value, optional) names whose list this is: setting a list
  -- replaces only that owner's earlier one, so two watchers can share a game.
  local breaks = {}
  function m.setBreakpoints(list, owner)
    owner = owner or "main"
    for key, bp in pairs(breaks) do
      if bp.owner == owner then
        local t = bankCache[bp.bank]
        if t then t[bp.addr % 0x4000] = bp.orig end
        breaks[key] = nil
      end
    end
    for _, bp in ipairs(list or {}) do
      local t = bank(bp.bank)
      local i = bp.addr % 0x4000
      if t[i] ~= 0xD3 then
        breaks[bp.bank * 65536 + bp.addr] = { bank = bp.bank, addr = bp.addr, orig = t[i], fn = bp.fn, owner = owner }
        t[i] = 0xD3
      end
    end
  end
  ops[0xD3] = function()
    local at = pc - 1
    local bp = breaks[((at < 0x4000) and 0 or romBank) * 65536 + at]
    if not bp then return 4 end
    bp.fn(a, b, c, d, e, h, l)
    return ops[bp.orig]()
  end

  -- direct memory access, for cheats and tools
  function m.peek(addr) return rd(addr) end
  -- a byte of the game itself: bank n (0 = the fixed first bank), address as the game sees it
  function m.peekRom(n, addr) return bank(n)[addr % 0x4000] end
  -- work memory 0xD000-0xDFFF in a given bank (1-7), whichever bank the game has switched in
  function m.peekBank(bank, addr) return wram[bank][addr - 0xD000] end
  -- (for Together, GBA/Ghosts.lua: video memory in either bank, and a sprite color as shown: palette * 4 + index)
  function m.peekVram(bank, addr) return (bank == 1 and vram1 or vram0)[addr - 0x8000] end
  function m.objColor(k) return objcol[k] end
  function m.poke(addr, v) wr(addr, v) end

  function m.debug()
    return { pc = pc, sp = sp, a = a, ly = ly, lcdc = lcdc, mode = mode, clk = clk, romBank = romBank,
             ds = ds, ime = ime, halted = halted, ie = ie, ifl = ifl, lcdOn = lcdOn }
  end

  return m
end
